/** Cron stays off the database critical path and only writes replayable root jobs. */
async function handleScheduled(env: Env, scheduledAt: number, cron: string): Promise<void> {
  const { enqueueScheduledRun, createProductAutoShelfRoot } = await import(
    "./services/order/ScheduledMaintenanceService"
  );
  if (cron === '* * * * *') {
    await env.ORDER_QUEUE.send(createProductAutoShelfRoot(scheduledAt), { contentType: 'json' });
    return;
  }
  const {createRechargeRefundRecoveryRoot}=await import('./services/payment/RechargeRefundRecoveryQueue');
  const {createRechargeRefundNoticeRoot}=await import('./services/payment/RechargeRefundNoticeQueue');
  await Promise.all([
    env.ORDER_QUEUE.send(createRechargeRefundRecoveryRoot(scheduledAt),{contentType:'json'}),
    env.ORDER_QUEUE.send(createRechargeRefundNoticeRoot(),{contentType:'json'}),
    env.ORDER_QUEUE.send({ action: 'dispatchProductVideoCleanup', scope: 'admin' }),
    env.ORDER_QUEUE.send({ action: 'dispatchProductVideoCleanup', scope: 'supplier' }),
    env.ORDER_QUEUE.send({
      action: "dispatchPaymentCallbackOutbox",
      scheduledAt,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchWechatCallbackOutbox",
      scheduledAt,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchMerchantShipmentCallbackOutbox",
      scheduledAt,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchCityDeliveryCallbacks",
      scheduledAt,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchPaymentReconciliation",
      scheduledAt,
      cursor: 0,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchWorkCallbackOutbox",
      scheduledAt,
    }),
    env.ORDER_QUEUE.send({
      action: "dispatchWorkContactActions",
      scheduledAt,
    }),
    enqueueScheduledRun(env, scheduledAt),
  ]);
}

