export class OrderNotificationDeliveryService extends OrderNotificationDeliveryDispatcher {
  constructor(container:Container,private readonly env:Env){super(container,env.ORDER_QUEUE);}

  async processMessage(
    message: OrderNotificationDeliveryMessage,
    fetcher: typeof fetch = fetch,
  ): Promise<ProcessingResult> {
    const shippingEnv = message.channel === 'wechat_shipping' ? captureRoutineShippingDeliveryEnv(this.env) : undefined;
    if (shippingEnv) {
      if (!Object.hasOwn(this.container.db, '$client') || !this.container.db.$client) return routineShippingUnavailable();
      // Prove the actual App LOGIN before changing a Queue claim. A missing
      // optional namespace is handled as a deterministic refusal after claim;
      // wrong principals or partial/drifted storage never receive that claim.
      await withTx(this.container, tx => assertRoutineShippingReadTx(tx));
      if(routineVirtualPaidKey(message.eventKey))await withTx(this.container,async tx=>{
        if(!await assertRoutineVirtualShippingSubjectsReadTx(tx))return routineShippingUnavailable();
      });
    }
    const subscriptionNotice = message.channel === 'wechat_routine' && routineSubscriptionNoticePrefix(message.eventKey);
    const subscriptionReady = subscriptionNotice && await routineSubscriptionDeliveryCommissioned(this.container);
    if (subscriptionNotice && (message.eventKey.startsWith('order.refund.success.notice:') || membershipPaidNoticeSubjectId(message.eventKey)!==null || rechargePaidNoticeSubjectId(message.eventKey)!==null || rechargeRefundSuccessNoticeKey(message.eventKey)) && !subscriptionReady)
      throw new WechatProviderConfigurationError('退款成功小程序通知的原账号协议尚未就绪');
    const subscriptionEnv = subscriptionReady ? captureRoutineSubscriptionDeliveryEnv(this.env) : undefined;
    const claim = await this.claim(message);
    if (typeof claim === "string") return claim;
    if (claim.channel === "wechat_shipping") return processRoutineShippingDelivery(this.container, shippingEnv!,
      { id: claim.id, eventKey: claim.eventKey, leaseToken: claim.leaseToken }, fetcher);
    if (subscriptionEnv) return processRoutineSubscriptionDelivery(this.container, subscriptionEnv,
      { id: claim.id, eventKey: claim.eventKey, leaseToken: claim.leaseToken }, fetcher);
    try {
      const result = await this.deliver(claim, fetcher);
      await this.finalize(claim, "SENT", result, "", Math.floor(Date.now() / 1_000));
      return "sent";
    } catch (error) {
      const now = Math.floor(Date.now() / 1_000);
      if (error instanceof WechatProviderConfigurationError) {
        await this.finalize(claim, "DEAD", undefined, errorText(error), now);
        return "dead";
      }
      if (error instanceof AliyunSmsRejectedError) {
        return this.recordRejected(claim, error.code, isAliyunRetryable(error.code), now);
      }
      if (error instanceof WechatProviderRejectedError) {
        return this.recordRejected(claim, String(error.code), error.retryable, now);
      }
